// 1. Using Compiler Built-ins (GCC/Clang) for safe addition
int x = INT_MAX;
int y = 1;
int result;
// Checks if x + y overflows INT, stores result if safe
if (__builtin_add_overflow(x, y, &result)) {
    // Overflow detected
    handle_overflow_error();
}


// 2. Explicitly Casting Operands (Multiplication)
// Ensures intermediate calculation uses 64-bit capacity
uint32_t a = 200000;
uint32_t b = 200000;
// Result is 40 Billion (overflows 32-bit int)
uint64_t safe_result = (uint64_t)a * b;


// 3. Manual Pre-check: Multiplication
// Check if a > ULLONG_MAX / b before calculation
uint64_t a_val, b_val;
// Assuming b_val > 0
if (a_val > ULLONG_MAX / b_val) {
    // Overflow guaranteed
    return false;
}
uint64_t result = a_val * b_val;
